// LinkedIn post content generator
const postTemplates = [
  "🚀 Excited to share that we're building an automation service for LinkedIn! Our agency is helping businesses streamline their social media presence and boost engagement. #LinkedInAutomation #DigitalMarketing #AgencyLife",

  "💼 At our agency, we're passionate about innovation. Currently developing a LinkedIn automation service that will revolutionize how businesses connect with their audience. Stay tuned! #Innovation #LinkedIn #BusinessGrowth",

  "🎯 Building something special at our agency - a LinkedIn automation service that will help businesses scale their social media presence efficiently. The future of digital marketing is here! #Automation #LinkedInMarketing #AgencyServices",

  "🔥 Our team is working on a game-changing LinkedIn automation service. Imagine posting consistently, engaging with your audience, and growing your network - all automated! #LinkedInGrowth #Automation #DigitalAgency",

  "📈 The future of LinkedIn marketing is automation! Our agency is developing a service that will help businesses maintain consistent, engaging content without the manual effort. #LinkedInAutomation #MarketingAgency #BusinessGrowth",

  "💡 Innovation alert! We're building a LinkedIn automation service at our agency. This will be a game-changer for businesses looking to scale their social media presence. #Innovation #LinkedIn #AgencyLife",

  "🚀 Day [DAY] of building our LinkedIn automation service! Our agency is committed to helping businesses thrive in the digital age. #LinkedInAutomation #AgencyServices #DigitalMarketing",

  "🎯 Consistency is key in social media! That's why our agency is developing a LinkedIn automation service. Stay tuned for updates on this exciting project! #Consistency #LinkedIn #AgencyInnovation"
];

// Get current day for dynamic content
const currentDate = new Date();
const dayOfYear = Math.floor((currentDate - new Date(currentDate.getFullYear(), 0, 0)) / (1000 * 60 * 60 * 24));

// Select a random template and customize it
const randomIndex = Math.floor(Math.random() * postTemplates.length);
let selectedTemplate = postTemplates[randomIndex];

// Replace [DAY] placeholder with actual day
selectedTemplate = selectedTemplate.replace('[DAY]', dayOfYear);

// Add some variety with hashtags
const additionalHashtags = [
  '#SocialMediaMarketing',
  '#BusinessAutomation', 
  '#DigitalTransformation',
  '#GrowthHacking',
  '#ContentMarketing',
  '#B2BMarketing',
  '#StartupLife',
  '#TechInnovation'
];

// Randomly add 2-3 additional hashtags
const numAdditionalHashtags = Math.floor(Math.random() * 3) + 2;
const shuffledHashtags = additionalHashtags.sort(() => 0.5 - Math.random());
const selectedHashtags = shuffledHashtags.slice(0, numAdditionalHashtags);

const finalPost = selectedTemplate + ' ' + selectedHashtags.join(' ');

return {
  json: {
    postContent: finalPost,
    postLength: finalPost.length,
    timestamp: new Date().toISOString(),
    templateUsed: randomIndex
  }
};

// Log successful post
const postData = $input.first().json;

console.log('✅ LinkedIn post created successfully!');
console.log('📝 Post content:', postData.postContent);
console.log('📊 Post length:', postData.postLength, 'characters');
console.log('🕒 Posted at:', new Date().toISOString());

return {
  json: {
    status: 'success',
    message: 'LinkedIn post created successfully',
    postId: postData.id,
    content: postData.postContent,
    timestamp: new Date().toISOString()
  }
};

// Log error for invalid content
console.log('❌ Post content too long or invalid');
console.log('📝 Content length:', $input.first().json.postLength, 'characters');
console.log('📝 Content:', $input.first().json.postContent);

return {
  json: {
    status: 'error',
    message: 'Post content exceeds LinkedIn character limit',
    postLength: $input.first().json.postLength,
    timestamp: new Date().toISOString()
  }
};
